def add(t,thesis,formula,params,cats,kill,risks,confidence='中低',status='限额观察'):
 # params: explicit three tuples (operating anchor, multiple, net cash, diluted shares); units USD million.
 vals=[None,None,None] if params is None else [round((a*b+c)/s,2) for a,b,c,s in params]
 refs=[dict(path=p,locator='公司原文经营模型、资本结构及风险章节；索引路径为冻结版本') for p in D[t]['sources']['company']]
 refs += [dict(source_id=s['id'],url=s['url']) for s in sources if s['ticker']==t]
 N.append(dict(rank=len(N)+1,ticker=t,thesis=thesis,horizon_months=15,price_date='2026-10-12',entry_price=float(D[t]['finance']['最新价格']),bear_price=vals[0],base_price=vals[1],bull_price=vals[2],valuation_formula=formula,scenario_inputs=params,catalysts=cats,kill_criteria=kill,key_risks=risks,evidence=refs,confidence=confidence,status=status))
