lines=['# R4 独立右尾与瓶颈研究','', '信息截止2026-10-12 19:40洛杉矶；价格采用10月12日正常收盘。245全池结构化筛查、30公司原文模型/融资/风险定向深读；六类输入为金融、公司、行业、背景、情景、对比。未读取其他角色。','', '核心提名是右尾争议池，不代表20只均可立即买入。PSIX、POET、KYTX、FLNC、AAOI、IREN应避免被纯价值筛选遗漏；现金与技术成功不能当股价地板。AAOI等基准低于现价仍因可识别右尾进入，仓位应服从失败损失预算。','', '全部倍数和未来股数为R4假设，经营锚来自冻结原文，非管理层承诺。各情景采用相容状态，不将所有最差因素叠成基准；不用概率加权伪精确目标。美元价格，模型金额百万美元。以15–18个月观察2027/早2028业绩可见性；不同财年明确保留。','', '|序|代码|收盘|悲观|基准|乐观|状态|','|---|---|---:|---:|---:|---:|---|']
for x in N: lines.append('|'+ '|'.join(str(x[k]) for k in ['rank','ticker','entry_price','bear_price','base_price','bull_price','status'])+'|')
for x in N:
 lines += ['',f"## {x['rank']}. {x['ticker']}",x['thesis'],'',x['valuation_formula'],'','催化：'+'；'.join(x['catalysts'])+'。','证伪：'+'；'.join(x['kill_criteria'])+'。','主要风险：'+'；'.join(x['key_risks'])+'。置信度：'+x['confidence']+'。','来源：'+ '；'.join(e.get('path',e.get('url','')) for e in x['evidence'])]
lines += ['','## 重点资本结构与右尾反求','POET：6月30日现金及证券796.342m；8月13日普通股173.058m、权证78.735m、期权5.369m、RSU4.253m，机械总数261.415m不是已发行也不是统一FD。Lumilens最多22.921m包含在总权证内，不重复加。五月19.048m单位融资400m，附26.25美元权证，2029-05-18到期；在本乐观价格下也并非全部价内。未假设这批权证行权现金。模型未来18月累计现金消耗/投入约196–236m；FD195–245m为对现有低价权证/客户归属/未来激励的压力估计，须逐项复核。若实际FD261.4m，基准值(109×8+600)/261.4=5.63美元，较220m分母再降约16%。净现金不是可强制返还资产。','KYTX：6月末199.427m现金证券，61.570m实股，10.590m期权+1.687m RSU；H1 FCF约-82.451m。150m净融资按5%费用、5/8美元发行需新增31.579/19.737m股；计旧奖励可能FD约93.6–105.4m，不能用旧61.6m分母给成功估值。成功2027年100疗程×0.55m=55m收入、贡献39m，固定现金费180m+投入10m，净消耗151m，合理跑道压力比简单年化更大。BLA/患者功能改善可在盈利前创造价值，但可靠事件rNPV缺口用null体现；反求621m权益要求不是目标。','FLNC：143.164m A类+41.433m B-1配对LLC单位=184.596m经济单位；模型195–205m含激励/可能融资，避免全收入只除A类。净债和可动现金须和受限信用证分开。','IREN：微软最低付款条款、预付款及资产融资降低客户需求尾部；FY27资本开支250–300亿美元与未来补充融资使每股值高度依赖期末债股。主表只是可证伪敏感性，不应作为已闭合目标价。','', '## 外部证据交叉与去重','COHR由NVIDIA客户侧确认采购与投资，区别供应商宣传；IREN签署微软SOW交叉合同/财报；KYTX公司临床稿含研究者解释，但仍为同一试验，不当成第二独立试验。POET的Lumilens公告和Q2报表是合同存在/资金两个不同问题；尚缺客户最终部署的独立证明。FLNC外部修复观点提供估值框架，再用官方指引和Up-C重算，不复制其目标。没有把多个转发页面当成多份独立确认。','', '## 候补/排除']
lines += [f'- {t}：{v}' for t,v in alts+ex]
lines += ['','## 待下一轮核验']+[f'- {q}' for q in out['open_questions']]
(R/'02_round1/R4_upside.md').write_text('\n'.join(lines),encoding='utf-8')
with (R/'07_logs/R4_full245_screen.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['ticker','category','price','price_date','validation','company_source_count','scenario_source_count','comparison_source_count','r4_status','reason']);w.writeheader()
 for x in U:
  t=x['ticker']; status='提名' if t in [n['ticker'] for n in N] else '候补' if t in dict(alts) else '排除' if t in dict(ex) else '本角色未优先深读'
  reason=next((n['thesis'] for n in N if n['ticker']==t),dict(alts+ex).get(t,'金融数据及资料覆盖已筛；相较本角色优先主题，未取得更强的3–18月可证伪非线性催化证据。不是全面公司否决。'))
  w.writerow(dict(ticker=t,category=x['category'],price=x['finance'].get('最新价格'),price_date=x['finance'].get('价格日期'),validation=x['finance'].get('估值校验'),company_source_count=len(x['sources'].get('company',[])),scenario_source_count=len(x['sources'].get('scenario',[])),comparison_source_count=len(x['sources'].get('comparison',[])),r4_status=status,reason=reason))
assert len(N)==20 and len(U)==245 and all(n['ticker'] in D for n in N)
